944-    try {
945-      await c.getByTestId('claim-void-reason').selectOption({ label: reason }, { timeout: 2000 });
946-    } catch {
947-      return false;             // not offered: the screen refuses it by leaving it out
948-    }
949-  } else if (reason !== undefined && action === 'settle') {
