808-/** Submit the open claim editor with `f` and judge the outcome. When the typed values are what the
809- *  row already shows, the save cannot be seen on the row: the step then counts as saved only once
810- *  no error has shown for a while (the `already` rule of until()). */
811-async function saveClaimEditor(page: Page, c: Locator, r: Locator, f: ClaimFields, what: string): Promise<boolean> {
812-  await fillClaimForm(r, f);
813-  const error = c.getByTestId('claim-error').or(r.getByTestId('claim-form-error'));
